   810  GLOBAL(void)
   811  jinit_d_coef_controller(j_decompress_ptr cinfo, boolean need_full_buffer)
   812  {
   813    my_coef_ptr coef;
   814
   815    coef = (my_coef_ptr)
   816      (*cinfo->mem->alloc_small) ((j_common_ptr)cinfo, JPOOL_IMAGE,
   817                                  sizeof(my_coef_controller));
   818    cinfo->coef = (struct jpeg_d_coef_controller *)coef;
   819    coef->pub.start_input_pass = start_input_pass;
   820    coef->pub.start_output_pass = start_output_pass;
   821  #ifdef BLOCK_SMOOTHING_SUPPORTED
   822    coef->coef_bits_latch = NULL;
   823  #endif
   824
   825    /* Create the coefficient buffer. */
   826    if (need_full_buffer) {
   827  #ifdef D_MULTISCAN_FILES_SUPPORTED
   828      /* Allocate a full-image virtual array for each component, */
   829      /* padded to a multiple of samp_factor DCT blocks in each direction. */
   830      /* Note we ask for a pre-zeroed array. */
   831      int ci, access_rows;
   832      jpeg_component_info *compptr;
   833
   834      for (ci = 0, compptr = cinfo->comp_info; ci < cinfo->num_components;
   835           ci++, compptr++) {
   836        access_rows = compptr->v_samp_factor;
   837  #ifdef BLOCK_SMOOTHING_SUPPORTED
   838        /* If block smoothing could be used, need a bigger window */
