   843          ((j_common_ptr)cinfo, JPOOL_IMAGE, TRUE,
   844           (JDIMENSION)jround_up((long)compptr->width_in_blocks,
   845                                 (long)compptr->h_samp_factor),
   846           (JDIMENSION)jround_up((long)compptr->height_in_blocks,
   847                                 (long)compptr->v_samp_factor),
   848           (JDIMENSION)access_rows);
   849      }
   850      coef->pub.consume_data = consume_data;
   851      coef->pub.decompress_data = decompress_data;
   852      coef->pub.coef_arrays = coef->whole_image; /* link to virtual arrays */
   853  #else
   854      ERREXIT(cinfo, JERR_NOT_COMPILED);
   855  #endif
   856    } else {
   857      /* We only need a single-MCU buffer. */
