   859      int i;
   860
   861      buffer = (JBLOCKROW)
   862        (*cinfo->mem->alloc_large) ((j_common_ptr)cinfo, JPOOL_IMAGE,
   863                                    D_MAX_BLOCKS_IN_MCU * sizeof(JBLOCK));
   864      for (i = 0; i < D_MAX_BLOCKS_IN_MCU; i++) {
   865        coef->MCU_buffer[i] = buffer + i;
   866      }
